(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = {};
  out.path = location.pathname;
  // 独立版：导航里只应该有「工具箱」，不能出现项目/社区/模板这些不存在的页面
  const links = [...document.querySelectorAll('header a')];
  out.nav = links.map((a) => ({ text: a.textContent.trim(), href: a.getAttribute('href') }));
  out.hasProjectsLink = links.some((a) => (a.getAttribute('href') || '').includes('/projects'));
  out.hasCommunityLink = links.some((a) => (a.getAttribute('href') || '').includes('/community'));
  out.logoHref = links[0]?.getAttribute('href') || null;

  // 元件库还能用
  const libBtn = [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.trim() === '元件库');
  out.libraryEntry = !!libBtn;
  libBtn?.click();
  await sleep(2400);
  out.cards = document.querySelectorAll('.lib-card').length;
  out.images = [...document.querySelectorAll('.lib-card img')].filter((i) => i.naturalWidth > 0).length;
  return JSON.stringify(out);
})()
